12	#include <cstdint>
13	#include <filesystem>
14	#include <fstream>
15	#include <functional>
16	#include <iostream>
17	#include <string>
18	#include <string_view>
19	#include <vector>
20	
21	#include "filehash.h"
22	#include "merkle.h"
23	
24	namespace {
25	
26	int g_failures = 0;
27	int g_checks = 0;
28	
29	void check(bool condition, std::string_view what) {
30	    ++g_checks;
31	    if (!condition) {
32	        ++g_failures;
33	        std::cerr << "FAIL: " << what << '\n';
34	    }
35	}
36	
37	namespace fs = std::filesystem;
38	
39	using branchaudit::Digest;
40	
41	std::string hex_of(const Digest& d) {
42	    return branchaudit::to_hex(d);
43	}
44	
45	Digest leaf_bytes(const std::vector<unsigned char>& data) {
46	    return branchaudit::merkle_leaf(data.data(), data.size());
47	}
48	
49	std::vector<unsigned char> bytes_of(std::string_view s) {
50	    return std::vector<unsigned char>(s.begin(), s.end());
51	}
52	
53	std::vector<unsigned char> fill_a(std::size_t n) {
54	    return std::vector<unsigned char>(n, static_cast<unsigned char>('a'));
55	}
56	
57	std::vector<unsigned char> pattern(std::size_t n) {
58	    std::vector<unsigned char> v(n);
59	    for (std::size_t i = 0; i < n; ++i) {
60	        v[i] = static_cast<unsigned char>((i * 31 + 7) % 256);
61	    }
62	    return v;
63	}
64	
65	struct TempArea {
66	    fs::path root;
67	    explicit TempArea(const std::string& tag) {
68	        const auto cwd_hash = std::hash<fs::path>{}(fs::current_path());
69	        root = fs::temp_directory_path() /
70	               ("branchaudit_merkle_test_" + tag + "_" +
71	                std::to_string(static_cast<std::uint64_t>(cwd_hash)));
72	        fs::remove_all(root);
73	        fs::create_directories(root);
74	    }
75	    ~TempArea() { std::error_code ec; fs::remove_all(root, ec); }
76	};
77	
78	void write_file(const fs::path& p, const std::vector<unsigned char>& bytes) {
79	    fs::create_directories(p.parent_path());
80	    std::ofstream out(p, std::ios::binary | std::ios::trunc);
81	    out.write(reinterpret_cast<const char*>(bytes.data()),
82	              static_cast<std::streamsize>(bytes.size()));
83	    check(static_cast<bool>(out), std::string("write fixture ") + p.string());
84	}
85	
86	Digest root_of(const std::vector<fs::path>& paths) {
87	    const branchaudit::FileHashResult r = branchaudit::merkle_root_files(paths);
88	    check(r.ok(), std::string("merkle_root_files succeeds: ") + r.error);
89	    return r.digest;
90	}
91	
92	// ---- 空批次根 -------------------------------------------------------------
93	
94	void test_empty_batch() {
95	    const Digest empty_root = branchaudit::merkle_empty_root();
96	    check(hex_of(empty_root) ==
97	              "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
98	          "empty batch root is SHA-256 of empty byte sequence");
99	
100	    const branchaudit::FileHashResult r =
101	        branchaudit::merkle_root_files({});
102	    check(r.ok(), "zero files: succeeds");
103	    check(r.digest == empty_root, "zero files: root equals merkle_empty_root()");
104	
105	    // 空批次根必须与“单个空文件”的叶子摘要不同。
106	    const Digest leaf_empty = leaf_bytes({});
107	    check(hex_of(leaf_empty) ==
108	              "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
109	          "leaf of empty file is SHA-256(0x00)");
110	    check(leaf_empty != empty_root,
111	          "empty batch root differs from single empty-file leaf");
112	}
113	
114	// ---- 叶子：0x00 前缀与原始字节 --------------------------------------------
115	
116	void test_leaf_rule() {
117	    check(hex_of(leaf_bytes(bytes_of("a"))) ==
118	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
119	          "leaf('a') = SHA-256(0x00 || 'a')");
120	    check(hex_of(leaf_bytes(bytes_of("abc"))) ==
121	              "609f6e36d2405585188d5cfd761f407c7cc46a7d3f314c88270469dde315fcd1",
122	          "leaf('abc') = SHA-256(0x00 || 'abc')");
123	    check(hex_of(leaf_bytes(bytes_of("hello\n"))) ==
124	              "54a6dc1bfc990ced3f5757264f357ad708a9ee54ce3d117299641b234f6d5800",
125	          "leaf('hello\\n') includes raw newline byte");
126	
127	    // 叶子不是普通 hash：0x00 前缀必须改变结果。
128	    branchaudit::Sha256 plain;
129	    const unsigned char a_byte = 'a';
130	    plain.update(&a_byte, 1);
131	    const Digest plain_a = plain.final();
132	    check(hex_of(plain_a) ==
133	              "ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb",
134	          "plain SHA-256('a') reference (no prefix)");
135	    check(leaf_bytes(bytes_of("a")) != plain_a,
136	          "leaf('a') must not equal plain hash('a')");
137	
138	    // 分组/填充边界长度的叶子（前缀使总长度 +1，覆盖各边界）。
139	    struct BCase { std::size_t n; const char* hex; };
140	    const BCase cases[] = {
141	        {55,  "2f96780fb415b287dd95897a04ef96fde6a5f5b0c771d0a1175543bc3250718e"},
142	        {56,  "4632d4b47c0932896996fe232ae65a5af500608fabd0bdbfbb6856795eaf9d85"},
143	        {63,  "5ec0fdb427bf003f71ceb018dfedc0028590a422eaf9f15a69dd1e5a6aa03d5e"},
144	        {64,  "88df0645999a1bc9dec19086e862403750a069436d7ecf7775256f78279b3fcb"},
145	        {65,  "3f104f71a21ddad6e23bac5b43967f5eed6675a5adf0c4050de374fff8055af7"},
146	        {128, "6023f14a3b7582c7e389f4ef3313bc3c6cbf69623e12a7d19485553d02d1f635"},
147	    };
148	    for (const BCase& c : cases) {
149	        check(hex_of(leaf_bytes(fill_a(c.n))) == c.hex,
150	              "leaf of 'a'*" + std::to_string(c.n) + " matches independent value");
151	    }
152	}
153	
154	// ---- 父节点：0x01 前缀、原始 32 字节、先左后右 -----------------------------
155	
156	void test_parent_rule() {
157	    const Digest la = leaf_bytes(bytes_of("a"));
158	    const Digest lbc = leaf_bytes(bytes_of("abc"));
159	
160	    check(hex_of(branchaudit::merkle_parent(la, lbc)) ==
161	              "6a5c0676c6dd1efd519348f49315879d99549029726d5dd1a5dedbf700720761",
162	          "parent(leaf('a'), leaf('abc')) = SHA-256(0x01||left||right)");
163	
164	    // 左右顺序不可交换。
165	    check(branchaudit::merkle_parent(la, lbc) != branchaudit::merkle_parent(lbc, la),
166	          "parent is ordered: parent(a,abc) != parent(abc,a)");
167	    check(hex_of(branchaudit::merkle_parent(lbc, la)) ==
168	              "ece02d1ac6ea17f528a19562aea6b77f7e7d1d8224a7583d3fbfc9f6e3d426ab",
169	          "parent(leaf('abc'), leaf('a')) independent value");
170	}
171	
172	// ---- 逐文件批次：顺序、重复、奇数提升、路径无关 ---------------------------
173	
174	void test_file_batches() {
175	    TempArea tmp("batches");
176	
177	    const auto empty = bytes_of("");
178	    const auto a = bytes_of("a");
179	    const auto abc = bytes_of("abc");
180	    const auto hello = bytes_of("hello\n");
181	
182	    const fs::path f_empty = tmp.root / "empty.bin";
183	    const fs::path f_a = tmp.root / "a.bin";
184	    const fs::path f_abc = tmp.root / "abc.bin";
185	    const fs::path f_hello = tmp.root / "hello.bin";
186	    write_file(f_empty, empty);
187	    write_file(f_a, a);
188	    write_file(f_abc, abc);
189	    write_file(f_hello, hello);
190	
191	    // 单文件批次：根即叶子摘要。
192	    check(hex_of(root_of({f_a})) == hex_of(leaf_bytes(a)),
193	          "single file: root equals its leaf digest");
194	    check(hex_of(root_of({f_a})) ==
195	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
196	          "single file root('a') is leaf, not plain hash");
197	    check(hex_of(root_of({f_empty})) ==
198	              "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
199	          "single empty file root differs from empty batch root");
200	
201	    // 两文件、顺序敏感。
202	    check(hex_of(root_of({f_a, f_abc})) ==
203	              "6a5c0676c6dd1efd519348f49315879d99549029726d5dd1a5dedbf700720761",
204	          "root [a, abc]");
205	    check(hex_of(root_of({f_abc, f_a})) ==
206	              "ece02d1ac6ea17f528a19562aea6b77f7e7d1d8224a7583d3fbfc9f6e3d426ab",
207	          "root [abc, a] differs when order is reversed");
208	
209	    // 三文件：末节点原样提升。结构 = parent(parent(La,Lbc), Lempty)。
210	    const Digest p = branchaudit::merkle_parent(leaf_bytes(a), leaf_bytes(abc));
211	    const Digest three = branchaudit::merkle_parent(p, leaf_bytes(empty));
212	    check(hex_of(three) ==
213	              "b3beb69a3342155ac93f8fb124f5b39ec5955cdcbff261495547e03361f9c99a",
214	          "structural 3-file root with odd promotion (independent value)");
215	    check(root_of({f_a, f_abc, f_empty}) == three,
216	          "root [a, abc, empty] matches promoted (not duplicated) structure");
217	
218	    // 明确排除“复制末节点”与“补零”两种错误配对。
219	    const Digest dup_last = branchaudit::merkle_parent(
220	        p, branchaudit::merkle_parent(leaf_bytes(empty), leaf_bytes(empty)));
221	    check(dup_last != three,
222	          "odd node is never duplicated to make a pair");
223	    const Digest zeros{};
224	    check(branchaudit::merkle_parent(p, zeros) != three,
225	          "odd node is never zero-padded to make a pair");
226	
227	    // 不同位置的重复排列给出不同根（不按摘要重排、不去重）。
228	    check(hex_of(root_of({f_a, f_a, f_abc})) ==
229	              "d2b37c5ec897ce0504f95ec7a060d88c38664164a4614b5ca18e5dd3df527702",
230	          "root [a, a, abc] keeps both positions");
231	    check(hex_of(root_of({f_a, f_abc, f_a})) ==
232	              "588340eb2a7896e08c25b9af5be4538358eadeb56e0c685910ac0cc6fb12e006",
233	          "root [a, abc, a] differs from [a, a, abc]");
234	
235	    // 同一路径重复传入，保留两个位置。
236	    check(hex_of(root_of({f_a, f_a})) ==
237	              "8025de747bafe2560d6b991bdb17ca89efe1b6fedda1be209c0ee015338861ea",
238	          "same path twice keeps two positions");
239	    // 两个不同文件、内容相同，结果与重复同一路径一致。
240	    const fs::path f_a_copy = tmp.root / "copy of a.bin";
241	    write_file(f_a_copy, a);
242	    check(root_of({f_a, f_a_copy}) == root_of({f_a, f_a}),
243	          "identical content in distinct files behaves like repeated positions");
244	
245	    // 偶数四文件与奇数五文件（末节点先提升，再与其左侧在上层配对）。
246	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello})) ==
247	              "ae395b1592efa07192377a24fc187eba186da891a39c12d3dfae9df84f0c9a93",
248	          "root of 4 files");
249	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello, f_a})) ==
250	              "685686ca622026c4537dfdb49e8f9dac110c553f1d21aee96633e12fa47a7c47",
251	          "root of 5 files (odd promotion across levels)");
252	
253	    // 七文件树：跨层多次奇数提升。
254	    const std::array<std::vector<unsigned char>, 7> seven_data = {
255	        empty, a, bytes_of("bb"), bytes_of("ccc"), bytes_of("dddd"),
256	        bytes_of("eeeee"), bytes_of("ffffff")};
257	    std::array<fs::path, 7> seven;
258	    for (std::size_t i = 0; i < seven.size(); ++i) {
259	        seven[i] = tmp.root / ("seven" + std::to_string(i) + ".bin");
260	        write_file(seven[i], seven_data[i]);
261	    }
262	    check(hex_of(root_of({seven.begin(), seven.end()})) ==
263	              "80bea6847da15bd2a145bbce5c01fb61672c4ad0f91da2e282075758d2610de2",
264	          "root of 7 files (independent multi-level value)");
265	
266	    // 根只反映各位置内容：相同有序内容放在不同路径（含空格/中文目录），
267	    // 根相同。
268	    const fs::path alt_dir = tmp.root / "子 目录" / "另一批";
269	    std::array<fs::path, 3> alt;
270	    alt[0] = alt_dir / "空.bin";
271	    alt[1] = alt_dir / "a file.dat";
272	    alt[2] = tmp.root / "深 路径" / "文 件.bin";
273	    write_file(alt[0], empty);
274	    write_file(alt[1], a);
275	    write_file(alt[2], abc);
276	    const Digest r1 = root_of({f_empty, f_a, f_abc});
277	    const Digest r2 = root_of({alt[0], alt[1], alt[2]});
278	    check(r1 == r2, "root is path-independent: same ordered contents, other paths");
279	    // 顺序不同则根不同，确认不是按路径或摘要排序。
280	    check(root_of({alt[2], alt[1], alt[0]}) != r2,
281	          "different position order yields different root even with same files");
282	}
283	
284	// ---- 相对路径按当前工作目录解释 -------------------------------------------
285	
286	void test_relative_paths() {
287	    TempArea tmp("relative");
288	    write_file(tmp.root / "r1.bin", bytes_of("a"));
289	    write_file(tmp.root / "r2.bin", bytes_of("a"));
290	
291	    const fs::path prev = fs::current_path();
292	    fs::current_path(tmp.root);
293	    const branchaudit::FileHashResult r =
294	        branchaudit::merkle_root_files({"r1.bin", "r2.bin"});
295	    fs::current_path(prev);
296	
297	    check(r.ok(), "relative paths resolved from current working directory");
298	    check(hex_of(r.digest) ==
299	              "8025de747bafe2560d6b991bdb17ca89efe1b6fedda1be209c0ee015338861ea",
300	          "relative-path batch root matches independent value");
301	}
302	
303	// ---- 失败：缺失、目录、任一失败即整次失败 ---------------------------------
304	
305	void test_failures() {
306	    TempArea tmp("fail");
307	    const fs::path good1 = tmp.root / "good1.bin";
308	    const fs::path good2 = tmp.root / "good2.bin";
309	    write_file(good1, bytes_of("a"));
310	    write_file(good2, bytes_of("abc"));
311	
312	    const fs::path missing = tmp.root / "does not exist 缺失.bin";
313	    auto names_path = [&](const branchaudit::FileHashResult& r) {
314	        return r.error.find(missing.string()) != std::string::npos;
315	    };
316	
317	    branchaudit::FileHashResult r = branchaudit::merkle_root_files({missing});
318	    check(!r.ok(), "only missing file: batch fails");
319	    check(names_path(r), "missing file: error names the failed path");
320	    check(r.error.size() > missing.string().size() + 2,
321	          "missing file: error gives a reason beyond the path");
322	
323	    // 缺失位于中间：报错指出该路径，而非用其余文件算出结果。
324	    r = branchaudit::merkle_root_files({good1, missing, good2});
325	    check(!r.ok(), "missing file in middle: whole batch fails");
326	    check(names_path(r), "middle failure names the middle path");
327	
328	    // 缺失位于最前。
329	    r = branchaudit::merkle_root_files({missing, good1});
330	    check(!r.ok() && names_path(r), "missing file first: fails on that path");
331	
332	    // 目录不是文件。
333	    const fs::path dir = tmp.root / "a dir 目录";
334	    fs::create_directories(dir);
335	    r = branchaudit::merkle_root_files({good1, dir, good2});
336	    check(!r.ok(), "directory among files: batch fails");
337	    check(r.error.find(dir.string()) != std::string::npos,
338	          "directory: error names the failed path");
339	    check(r.error.find("directory") != std::string::npos,
340	          "directory: error states directory reason");
341	}
342	
343	// ---- 大文件：流式读取、尾部敏感 -------------------------------------------
344	
345	void test_large_files() {
346	    TempArea tmp("large");
347	    const std::vector<unsigned char> big = fill_a(200000);
348	    const std::vector<unsigned char> pat = pattern(200000);
349	    const fs::path f_big = tmp.root / "a200000.bin";
350	    const fs::path f_pat = tmp.root / "pattern200000.bin";
351	    write_file(f_big, big);
352	    write_file(f_pat, pat);
353	
354	    check(hex_of(root_of({f_big})) ==
355	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
356	          "single large file leaf (streaming)");
357	    check(hex_of(root_of({f_big, f_pat})) ==
358	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
359	          "root [big, pattern]");
360	    check(hex_of(root_of({f_pat, f_big})) ==
361	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
362	          "root [pattern, big] differs under reversal");
363	
364	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
365	    std::vector<unsigned char> tail = big;
366	    tail.back() = static_cast<unsigned char>('b');
367	    const fs::path f_tail = tmp.root / "a200000tail.bin";
368	    write_file(f_tail, tail);
369	    check(hex_of(root_of({f_tail})) ==
370	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
371	          "large file: changing last byte changes leaf/root");
372	    check(root_of({f_tail}) != root_of({f_big}),
373	          "large file: tail change is detected");
374	}
375	
376	}  // namespace
377	
378	int main() {
379	    test_empty_batch();
380	    test_leaf_rule();
381	    test_parent_rule();
382	    test_file_batches();
383	    test_relative_paths();
384	    test_failures();
385	    test_large_files();
386	
387	    if (g_failures == 0) {
388	        std::cout << "all " << g_checks << " merkle regression checks passed\n";
389	        return 0;
390	    }
391	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
392	    return 1;
393	}
